1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  SECRET_PROVIDERS,
5	  type SecretProvider,
6	  createSecretSchema,
7	  rotateSecretSchema,
8	  updateSecretSchema,
9	} from "@paperclipai/shared";
10	import { validate } from "../middleware/validate.js";
11	import { assertBoard, assertCompanyAccess } from "./authz.js";
12	import { logActivity, secretService } from "../services/index.js";
13	
14	export function secretRoutes(db: Db) {
15	  const router = Router();
16	  const svc = secretService(db);
17	  const configuredDefaultProvider = process.env.PAPERCLIP_SECRETS_PROVIDER;
18	  const defaultProvider = (
19	    configuredDefaultProvider && SECRET_PROVIDERS.includes(configuredDefaultProvider as SecretProvider)
20	      ? configuredDefaultProvider
21	      : "local_encrypted"
22	  ) as SecretProvider;
23	
24	  router.get("/companies/:companyId/secret-providers", (req, res) => {
25	    assertBoard(req);
26	    const companyId = req.params.companyId as string;
27	    assertCompanyAccess(req, companyId);
28	    res.json(svc.listProviders());
29	  });
30	
31	  router.get("/companies/:companyId/secrets", async (req, res) => {
32	    assertBoard(req);
33	    const companyId = req.params.companyId as string;
34	    assertCompanyAccess(req, companyId);
35	    const secrets = await svc.list(companyId);
36	    res.json(secrets);
37	  });
38	
39	  router.post("/companies/:companyId/secrets", validate(createSecretSchema), async (req, res) => {
40	    assertBoard(req);
41	    const companyId = req.params.companyId as string;
42	    assertCompanyAccess(req, companyId);
43	
44	    const created = await svc.create(
45	      companyId,
46	      {
47	        name: req.body.name,
48	        provider: req.body.provider ?? defaultProvider,
49	        value: req.body.value,
50	        description: req.body.description,
51	        externalRef: req.body.externalRef,
52	      },
53	      { userId: req.actor.userId ?? "board", agentId: null },
54	    );
55	
56	    await logActivity(db, {
57	      companyId,
58	      actorType: "user",
59	      actorId: req.actor.userId ?? "board",
60	      action: "secret.created",
61	      entityType: "secret",
62	      entityId: created.id,
63	      details: { name: created.name, provider: created.provider },
64	    });
65	
66	    res.status(201).json(created);
67	  });
68	
69	  router.post("/secrets/:id/rotate", validate(rotateSecretSchema), async (req, res) => {
70	    assertBoard(req);
71	    const id = req.params.id as string;
72	    const existing = await svc.getById(id);
73	    if (!existing) {
74	      res.status(404).json({ error: "Secret not found" });
75	      return;
76	    }
77	    assertCompanyAccess(req, existing.companyId);
78	
79	    const rotated = await svc.rotate(
80	      id,
81	      {
82	        value: req.body.value,
83	        externalRef: req.body.externalRef,
84	      },
85	      { userId: req.actor.userId ?? "board", agentId: null },
86	    );
87	
88	    await logActivity(db, {
89	      companyId: rotated.companyId,
90	      actorType: "user",
91	      actorId: req.actor.userId ?? "board",
92	      action: "secret.rotated",
93	      entityType: "secret",
94	      entityId: rotated.id,
95	      details: { version: rotated.latestVersion },
96	    });
97	
98	    res.json(rotated);
99	  });
100	
101	  router.patch("/secrets/:id", validate(updateSecretSchema), async (req, res) => {
102	    assertBoard(req);
103	    const id = req.params.id as string;
104	    const existing = await svc.getById(id);
105	    if (!existing) {
106	      res.status(404).json({ error: "Secret not found" });
107	      return;
108	    }
109	    assertCompanyAccess(req, existing.companyId);
110	
111	    const updated = await svc.update(id, {
112	      name: req.body.name,
113	      description: req.body.description,
114	      externalRef: req.body.externalRef,
115	    });
116	
117	    if (!updated) {
118	      res.status(404).json({ error: "Secret not found" });
119	      return;
120	    }
121	
122	    await logActivity(db, {
123	      companyId: updated.companyId,
124	      actorType: "user",
125	      actorId: req.actor.userId ?? "board",
126	      action: "secret.updated",
127	      entityType: "secret",
128	      entityId: updated.id,
129	      details: { name: updated.name },
130	    });
131	
132	    res.json(updated);
133	  });
134	
135	  router.delete("/secrets/:id", async (req, res) => {
136	    assertBoard(req);
137	    const id = req.params.id as string;
138	    const existing = await svc.getById(id);
139	    if (!existing) {
140	      res.status(404).json({ error: "Secret not found" });
141	      return;
142	    }
143	    assertCompanyAccess(req, existing.companyId);
144	
145	    const removed = await svc.remove(id);
146	    if (!removed) {
147	      res.status(404).json({ error: "Secret not found" });
148	      return;
149	    }
150	
151	    await logActivity(db, {
152	      companyId: removed.companyId,
153	      actorType: "user",
154	      actorId: req.actor.userId ?? "board",
155	      action: "secret.deleted",
156	      entityType: "secret",
157	      entityId: removed.id,
158	      details: { name: removed.name },
159	    });
160	
161	    res.json({ ok: true });
162	  });
163	
164	  return router;
165	}
